/**
 * Types of the "v2" data payload (generated by
 * local_scripts/clean/export_v2.py).
 *
 * This is a completely separate data set from the hand maintained
 * `public/data.json`; nothing here is shared with `views/DataSearcher`.
 */

export interface LocalizedName {
    name?: string | null;
    name_jp?: string | null;
    name_en?: string | null;
}

export interface Ref {
    id: number;
    name?: string | null;
    name_jp?: string | null;
    name_en?: string | null;
}

export interface JobRef extends Ref {
    primary?: boolean;
}

export interface FateSkill extends LocalizedName {
    identification: number;
    type: string | null;
}

export interface CharacterListItem extends LocalizedName {
    id: number;
    group: number;
    guide_no: number | null;
    style: string;
    is_default_style: boolean;
    rarity: Ref;
    race: Ref;
    attribute: Ref;
    gender: Ref;
    personality: Ref;
    alignment: { id: number; name: string; point: number };
    jobs: JobRef[];
    fate: FateSkill | null;
    /** 克己：``extra_tags`` 为比同稀有度标准值更高（或专属）的属性 */
    self_restraint: { id: number | null; extra_tags: string[] } | null;
    /** 潜在继承技能的解锁等级（``sub_inheritance_grade_id``） */
    potential_grade: number | null;
    /** 卡池组：-1 限定 / -2 联动 / 0 共用 / 1 Ⅰ组 / 2 Ⅱ组 */
    pool_group: number;
    /** 声优（手工补充） */
    character_voice: string | null;
    /** 上线日期（手工补充） */
    release_date: { date: string | null; time: string | null; milliseconds: number } | null;
    images?: {
        image?: string | null;
        /** thumbnail sprite stem, e.g. ``tmb_chara_01001_00_02`` */
        thumbnail?: string | null;
        /** callable file name, e.g. ``tmb_chara_01001_00_02.png`` */
        thumbnail_file?: string | null;
        /** source folder of the sprite: ``chara`` / ``gasha`` */
        thumbnail_dir?: string | null;
    };
}

export interface SkillRef extends LocalizedName {
    identification: number;
    id?: number;
    level?: number;
    need_point?: number;
    skill_level?: number;
}

export interface CharacterDetail extends CharacterListItem {
    stats: {
        base: Record<StatKey, number>;
        growth: Record<StatKey, number>;
        pools: Record<string, { base: number | null; growth: number | null }>;
        growth_rate: Array<Record<string, number | null>>;
    };
    talent: {
        id: number;
        name: string | null;
        name_jp: string | null;
        min: Record<StatKey, number>;
        max: Record<StatKey, number>;
    };
    skills: {
        unique: SkillRef[];
        inherit: SkillRef[];
        potential_inherit: SkillRef[];
        discipline: SkillRef[];
        same_identifications: number[];
        exclude_inheritance: number[];
        get_lv: number | null;
    };
    mental: { id: number; value: number | null };
    grade: Ref;
    voice?: {
        speech?: Record<string, string> | string | null;
        breakup_speech?: Record<string, string> | string | null;
        voice_group_id?: number | null;
    };
}

export interface CharacterStyle {
    id: number;
    caption: string;
    is_default: boolean;
    awakening: number | null;
    before_awakening: number | null;
}

export type StatKey = 'str' | 'int' | 'pie' | 'vit' | 'agi' | 'dex' | 'luk';

export interface JobSkill extends LocalizedName {
    identification: number;
    get_lv: number | null;
}

export interface JobDetail extends LocalizedName {
    id: number;
    abbreviation?: string | null;
    display_order: number;
    category: 'standard' | 'collab' | 'character' | 'other';
    alignment: Record<string, boolean>;
    base: Record<string, number | null>;
    growth: Record<string, number | null>;
    multipliers: Record<string, number | null>;
    skills: JobSkill[];
    skill_variants: Record<string, JobSkill[]>;
    skill_count: number;
    characters: { primary: number[]; changeable: number[] };
    /** 转职到本职业所需的道具（按角色组给，道具名暂缺） */
    change_items: Array<{ item: number | null; quantity: number | null; group: number | null }>;
}

export interface EffectParamLabel {
    /** 名称；末尾带 ``%`` 表示该值是百分数（显示时 ``%`` 移到数值后面） */
    name: string;
    /** @deprecated 旧数据里的单位，现已改用名称末尾的 ``%`` */
    unit?: string;
}

export interface EffectKind {
    id: number;
    name: string | null;
    name_jp: string | null;
    category: number | null;
    primary_category: number | null;
    count: number;
    /** labels for param_1..7; null position = unknown / unused */
    params?: Array<EffectParamLabel | null> | null;
    /** 互斥 / 互相移除的效果种类（暂无可读枚举） */
    invalid_kinds?: number[] | null;
    remove_kinds?: number[] | null;
}

export interface SkillListItem extends LocalizedName {
    identification: number;
    kind: number | null;
    kind_name: string | null;
    max_level: number;
    is_passive: boolean;
    player: boolean;
    sources: string[];
    jobs: number[];
    flags: { test: boolean; level0: boolean; player: boolean };
    /** 技能用到的 sub effect kind（去重升序），供列表按 ID 精确筛选 */
    sub_kinds: number[];
}

export interface SkillDamage {
    attack_rate: number | null;
    attack_rate_both_hands?: number | null;
    add_damage_rate: number | null;
    add_critical_rate?: number | null;
    valid_cap_parameter_value?: number | null;
    valid_cap_parameter_value_both_hands?: number | null;
    valid_start_parameter_value?: number | null;
    damage_type: number | null;
    attack_type?: number | null;
    /** stat the attack rate is a percentage of (SkillReferenceParamType) */
    reference_parameter?: number | null;
    /** second stat scaled into the attack rate (double-scaling skills) */
    reference_parameter_2?: number | null;
    /** element ids: 1 fire .. 7 untyped, 99 physical, 999 none */
    aptitude_ids?: number[];
    fixed_damage: number | null;
    hit_rate: number | null;
    damage_count: number | null;
    only_once?: boolean | null;
    target: number | null;
    target_text: string | null;
}

/** 被引用的 sub effect 的摘要（用于把「追加子效果 / 扩展参数」展开成描述） */
export interface SubEffectBriefLeaf {
    id: number;
    kind: number | null;
    kind_name: string | null;
    params: number[] | null;
    strength: number | null;
    turn: number | null;
    target: number | null;
    target_text: string | null;
}

/** 只再展开一层：``children`` 是叶子 */
export interface SubEffectBrief extends SubEffectBriefLeaf {
    children: SubEffectBriefLeaf[];
}

export interface SkillSubEffect {
    kind: number | null;
    kind_name: string | null;
    strength: number | null;
    turn: number | null;
    target: number | null;
    target_text: string | null;
    params?: Array<number | null>;
    /** labels for ``params``, from effect_kinds.json */
    param_labels?: Array<EffectParamLabel | null> | null;
    /** where the sub effect was attached: the damage row, the effect group, or the attack start */
    from?: 'damage' | 'effect_group' | 'attack_start';
    /** ``SkillSubEffect.reference_parameter`` (SkillReferenceParamType id) */
    reference_parameter?: number | null;
    /** base apply rate in percent; the actual rate scales with ``reference_parameter`` */
    reference_parameter_rate?: number | null;
    /** stat value below which the apply rate is 0 */
    abnormal_valid_start_parameter_value?: number | null;
    /** stat value at which the apply rate reaches 100% */
    abnormal_valid_cap_parameter_value?: number | null;
    /** the effect ignores the apply check entirely */
    force_apply?: boolean | null;
    /** resistance is not subtracted from the apply rate */
    is_ignore_resist?: boolean | null;
    /** 施加率参照的抗性类型（暂无可读枚举） */
    reference_resist?: number | null;
    /** 追加的子效果 id */
    child_sub_effect_ids?: number[] | null;
    /** 只对特定种族生效 */
    target_race_ids?: number[] | null;
    /** ``SkillSubEffectExtensionParam`` 的扩展参数（多数是别的 sub effect id） */
    extension_params?: number[] | null;
    /** 参数里指向的效果（参数序号 -> 被引用效果的摘要） */
    param_refs?: Record<string, SubEffectBrief> | null;
    /** ``child_sub_effect_ids`` 的展开版 */
    child_sub_effects?: SubEffectBrief[] | null;
    /** ``extension_params`` 的展开版 */
    extension_effects?: SubEffectBrief[] | null;
    /** 效果量（恢复量等）参照的能力值：2 魔力 / 3 神力 / 22 信仰 / 23 体力 / 25 灵巧 / 26 运气 / 27 等级 */
    calc_reference_parameter?: number | null;
    /** 第二个参照能力值（双属性折算时用） */
    calc_reference_parameter_2?: number | null;
    /** 效果量占参照能力的百分比，140 = 140% */
    calc_reference_parameter_rate?: number | null;
    /** 第二个参照能力值的百分比 */
    calc_reference_parameter_rate_2?: number | null;
    /** 效果量的参数上限（阈值），如 100 / 800 */
    calc_valid_cap_parameter_value?: number | null;
    /** 效果量的阈值起点 */
    calc_valid_start_parameter_value?: number | null;
}

export interface SkillLevel {
    level: number;
    cost: number | null;
    cost_kind: number | null;
    use_timing: number | null;
    /** 每场战斗的可用次数（0 = 不限） */
    use_limit?: number | null;
    /** 仇恨值 */
    hate?: number | null;
    /** 技能射程：0 近距离 / 1 中距离 / 10 远距离 / 99 依武器 */
    range_type?: number | null;
    /** 使用条件 id（暂无可读枚举） */
    skill_condition_ids?: number[] | null;
    effect_group?: number;
    passive_effect_groups?: number[];
    description?: string;
    description_lang?: string;
    damage?: SkillDamage[];
    sub_effects?: SkillSubEffect[];
}

export interface SkillLearn {
    job: number;
    get_lv: number | null;
}

export interface SkillDetail extends SkillListItem {
    description: string | null;
    detail_description: string | null;
    description_lang?: string;
    job_limited: number[];
    equipment_limited: number[];
    tags: number[];
    levels: SkillLevel[];
    /** "Lv 3 盗贼" style unlock conditions */
    learn?: SkillLearn[];
}

export interface Manifest {
    /** ``Api/Version`` payload - the only value the cache is keyed on */
    version: number | null;
    source: string;
    counts: {
        characters: number;
        character_groups: number;
        excluded_awakening: number;
        jobs: number;
        skills: number;
        player_skills: number;
    };
    notes: string[];
}
